const languageToggle = document.querySelector('[data-site-language-toggle]');
const textNodes = [];
const textWalker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
  acceptNode(node) {
    if (!node.nodeValue.trim() || node.parentElement.closest('script, style, code, [data-policy-language="en"], [data-policy-language="tr"]')) return NodeFilter.FILTER_REJECT;
    return NodeFilter.FILTER_ACCEPT;
  }
});
while (textWalker.nextNode()) textNodes.push({ node: textWalker.currentNode, english: textWalker.currentNode.nodeValue });

const translatedAttributes = [];
const translatableAttributes = ['alt', 'aria-label', 'placeholder', 'title', 'content', 'data-caption'];
for (const element of document.querySelectorAll('*')) {
  for (const attribute of translatableAttributes) {
    const value = element.getAttribute(attribute);
    if (value) translatedAttributes.push({ element, attribute, english: value });
  }
}

const englishTitle = document.title;
const pageTitleTr = sitePageTitles[englishTitle] || englishTitle;
const docsSectionEnglish = new Map([...document.querySelectorAll('.docs-section[data-title]')].map((section) => [section, { title: section.dataset.title, group: section.dataset.group }]));
const docsLabelsEnglish = new Map([...document.querySelectorAll('.docs-nav-label')].map((label) => [label, label.textContent.trim()]));

function applySiteLanguage(language) {
  const isTurkish = language === 'tr';
  document.documentElement.lang = language;
  document.title = isTurkish ? pageTitleTr : englishTitle;

  for (const { node, english } of textNodes) {
    const translation = isTurkish ? normalizedSiteTranslations[english.trim()] : null;
    node.nodeValue = translation ? english.replace(english.trim(), translation) : english;
  }
  for (const { element, attribute, english } of translatedAttributes) {
    element.setAttribute(attribute, isTurkish ? (siteAttributeTranslations[english] || siteTranslations[english] || english) : english);
  }
  for (const element of document.querySelectorAll('[data-policy-language]')) {
    element.hidden = element.dataset.policyLanguage !== language;
  }
  for (const [section, original] of docsSectionEnglish) {
    section.dataset.title = isTurkish ? (siteTranslations[original.title] || original.title) : original.title;
    section.dataset.group = isTurkish ? (siteTranslations[original.group] || original.group) : original.group;
  }
  for (const section of document.querySelectorAll('.docs-section[data-group]')) {
    const original = docsSectionEnglish.get(section);
    if (original) continue;
    if (!section.dataset.englishGroup) section.dataset.englishGroup = section.dataset.group;
    section.dataset.group = isTurkish ? (siteTranslations[section.dataset.englishGroup] || section.dataset.englishGroup) : section.dataset.englishGroup;
  }
  for (const button of document.querySelectorAll('.docs-nav-link')) {
    const targetId = button.getAttribute('href')?.slice(1);
    const target = targetId ? document.getElementById(targetId) : null;
    const original = docsSectionEnglish.get(target)?.title;
    if (original) button.textContent = isTurkish ? (siteTranslations[original] || original) : original;
  }
  for (const [label, english] of docsLabelsEnglish) {
    label.textContent = isTurkish ? (siteTranslations[english] || english) : english;
  }

  if (languageToggle) {
    languageToggle.textContent = isTurkish ? 'TR' : 'EN';
    languageToggle.setAttribute('aria-label', isTurkish ? 'Türkçe. İngilizceye geç' : 'English. Switch to Turkish');
    languageToggle.setAttribute('aria-pressed', String(isTurkish));
  }
  for (const link of document.querySelectorAll('a[href]')) {
    const href = link.getAttribute('href');
    if (!href || href.startsWith('#')) continue;
    if (/^[a-z][a-z\d+.-]*:/i.test(href) || href.startsWith('//')) {
      try {
        const externalUrl = new URL(href, location.href);
        if (!['zelixos.com', 'www.zelixos.com', 'docs.zelixos.com'].includes(externalUrl.hostname)) continue;
        if (!link.dataset.englishHref) link.dataset.englishHref = href;
        const originalUrl = new URL(link.dataset.englishHref, location.href);
        originalUrl.searchParams.set('lang', language);
        link.setAttribute('href', originalUrl.href);
      } catch {}
      continue;
    }
    if (!link.dataset.englishHref) link.dataset.englishHref = href;
    try {
      const localizedUrl = new URL(link.dataset.englishHref, location.href);
      localizedUrl.searchParams.set('lang', language);
      const originalUrl = new URL(link.dataset.englishHref, location.href);
      link.setAttribute('href', `${localizedUrl.pathname}${localizedUrl.search}${originalUrl.hash}`);
    } catch {}
  }
}

if (languageToggle) {
  languageToggle.addEventListener('click', () => {
    const nextLanguage = document.documentElement.lang === 'tr' ? 'en' : 'tr';
    try { localStorage.setItem('zelixos-language', nextLanguage); } catch {}
    applySiteLanguage(nextLanguage);
    try {
      const currentUrl = new URL(location.href);
      currentUrl.searchParams.set('lang', nextLanguage);
      history.replaceState(null, '', currentUrl);
    } catch {}
    document.dispatchEvent(new CustomEvent('site-language-change', { detail: { language: nextLanguage } }));
  });
}

let savedLanguage = 'en';
try { savedLanguage = new URL(location.href).searchParams.get('lang') || localStorage.getItem('zelixos-language') || 'en'; } catch {}
try { localStorage.setItem('zelixos-language', savedLanguage); } catch {}
applySiteLanguage(savedLanguage);
